/*
 * Headless end-to-end check for the AR page using Playwright + a fake camera.
 *
 *   node tools/headless_check.cjs [--compile] [--video path.y4m]
 *
 * --compile   rebuild targets/targets.mind from targets/target.png first (uses compile.html)
 * --video     fake camera clip (default: a clip generated by make_fake_camera.py in a temp dir)
 *
 * It starts a local static server, opens index.html in headless Chromium whose camera plays the
 * clip, waits for MindAR to detect the target, screenshots the pop-up, taps it and checks that the
 * Instagram URL from config.js is opened.
 */
const path = require("path");
const fs = require("fs");
const os = require("os");
const http = require("http");
const { execFileSync } = require("child_process");
const { chromium } = require("playwright");

const AR_DIR = path.resolve(__dirname, "..");
const args = process.argv.slice(2);
const doCompile = args.includes("--compile");
let video = args.includes("--video") ? args[args.indexOf("--video") + 1] : null;

const TYPES = { ".html": "text/html", ".js": "text/javascript", ".png": "image/png", ".jpg": "image/jpeg",
  ".mind": "application/octet-stream", ".txt": "text/plain" };

function serve() {
  const server = http.createServer((req, res) => {
    let p = decodeURIComponent(new URL(req.url, "http://x").pathname);
    if (p.endsWith("/")) p += "index.html";
    const file = path.join(AR_DIR, p);
    if (!file.startsWith(AR_DIR) || !fs.existsSync(file) || fs.statSync(file).isDirectory()) {
      res.writeHead(404); return res.end("not found");
    }
    res.writeHead(200, { "content-type": TYPES[path.extname(file)] || "application/octet-stream" });
    fs.createReadStream(file).pipe(res);
  });
  return new Promise((resolve) => server.listen(0, "127.0.0.1", () => resolve(server)));
}

(async () => {
  const outDir = fs.mkdtempSync(path.join(os.tmpdir(), "ar-check-"));
  if (!video) {
    video = path.join(outDir, "camera.y4m");
    execFileSync("python3", ["-I", path.join(__dirname, "make_fake_camera.py"), path.join(AR_DIR, "targets/target.png"), video], { stdio: "inherit" });
  }
  const server = await serve();
  const base = `http://127.0.0.1:${server.address().port}/`;
  // The full Chromium build is needed: the "headless shell" has no usable WebGL for tfjs,
  // which MindAR needs for both compiling and tracking.
  const browser = await chromium.launch({
    channel: "chromium",
    args: ["--use-fake-ui-for-media-stream", "--use-fake-device-for-media-stream",
      `--use-file-for-fake-video-capture=${video}`, "--enable-unsafe-swiftshader", "--ignore-gpu-blocklist"],
  });
  let failed = false;
  try {
    if (doCompile) {
      const page = await browser.newPage();
      page.on("pageerror", (e) => console.error("[compile] page error:", e.message));
      await page.goto(base + "compile.html");
      console.log("compiling targets/target.png …");
      const t0 = Date.now();
      const b64 = await page.evaluate(() => window.compileFromUrls(["targets/target.png"]));
      const out = path.join(AR_DIR, "targets/targets.mind");
      fs.writeFileSync(out, Buffer.from(b64, "base64"));
      console.log(`wrote ${out} (${fs.statSync(out).size} bytes) in ${((Date.now() - t0) / 1000).toFixed(1)}s`);
      await page.close();
    }

    const config = {};
    new Function("window", fs.readFileSync(path.join(AR_DIR, "config.js"), "utf8"))(config);
    const instagramUrl = config.AR_CONFIG.instagramUrl;

    const context = await browser.newContext({ viewport: { width: 390, height: 844 }, permissions: ["camera"] });
    await context.route(/instagram\.com/, (route) => route.fulfill({ contentType: "text/html", body: "<title>stub</title>" }));
    const page = await context.newPage();
    const errors = [];
    page.on("pageerror", (e) => errors.push(e.message));
    page.on("console", (m) => { if (m.type() === "error") errors.push(m.text()); });
    await page.addInitScript(() => {
      window.__ar = [];
      for (const n of ["arReady", "arError", "targetFound", "targetLost"]) {
        document.addEventListener(n, () => window.__ar.push(n));
      }
    });
    await page.goto(base);
    await page.waitForFunction(() => window.__ar.includes("arReady") || window.__ar.includes("arError"), null, { timeout: 90000 });
    if (await page.evaluate(() => window.__ar.includes("arError"))) throw new Error("AR failed to start (arError)");
    console.log("AR ready; waiting for the target to be detected …");
    await page.waitForFunction(() => window.__ar.includes("targetFound"), null, { timeout: 90000 });
    console.log("target found");
    await page.waitForSelector("#ig-button:not(.hidden)", { timeout: 5000 });
    // The camera feed must be playing and cover the viewport (headless screenshots show it black, so check the DOM).
    const videoState = await page.evaluate(() => {
      const v = document.querySelector("video"); if (!v) return null;
      const r = v.getBoundingClientRect();
      return { w: v.videoWidth, h: v.videoHeight, paused: v.paused, covers: r.width >= innerWidth && r.height >= innerHeight };
    });
    if (!videoState || !videoState.w || videoState.paused || !videoState.covers) throw new Error("camera feed not playing full-screen: " + JSON.stringify(videoState));
    console.log("camera feed:", JSON.stringify(videoState));
    const uiButtons = await page.$$eval(".a-enter-vr, .a-enter-ar", (els) => els.filter((e) => e.offsetParent !== null).length);
    if (uiButtons) throw new Error("A-Frame VR/AR/fullscreen button is visible");
    await page.waitForTimeout(1200); // let the pop-up animation finish
    const shot = path.join(outDir, "ar-popup.png");
    await page.screenshot({ path: shot });
    console.log("screenshot:", shot);

    const [popup] = await Promise.all([
      context.waitForEvent("page", { timeout: 10000 }),
      page.mouse.click(195, 422),
    ]);
    const opened = popup.url();
    console.log("tap opened:", opened);
    if (!opened.startsWith(instagramUrl)) throw new Error(`expected ${instagramUrl}, got ${opened}`);
    const btnHref = await page.$eval("#ig-button", (a) => a.href);
    if (btnHref !== instagramUrl) throw new Error(`button href ${btnHref} != ${instagramUrl}`);
    const relevant = errors.filter((e) => !/favicon/.test(e));
    if (relevant.length) { console.error("page errors:", relevant); failed = true; }
    console.log(failed ? "FAIL" : "PASS");
  } catch (e) {
    failed = true;
    console.error("FAIL:", e.message);
  } finally {
    await browser.close();
    server.close();
  }
  process.exit(failed ? 1 : 0);
})();
